import json, sys, collections
from pathlib import Path
NORM = {"results.json": {"derivation"}, "manifest.json": {"baseline", "protocol", "oxide_source", "derivation"}}
def walk(a, b, keys, path, counts, diffs):
    if isinstance(a, dict) and isinstance(b, dict):
        if a.keys() != b.keys(): diffs.append(f"{path}: keys {sorted(a.keys() ^ b.keys())}"); return
        for k in a:
            if k in keys and a[k] != b[k] and not isinstance(a[k], (dict, list)):
                counts[k] += 1; continue
            if k in keys and isinstance(a[k], (dict,list)) and a[k] != b[k] and k == "derivation":
                counts[k] += 1; continue
            walk(a[k], b[k], keys, f"{path}.{k}", counts, diffs)
    elif isinstance(a, list) and isinstance(b, list):
        if len(a) != len(b): diffs.append(f"{path}: len"); return
        for i, (x, y) in enumerate(zip(a, b)): walk(x, y, keys, f"{path}[{i}]", counts, diffs)
    elif a != b: diffs.append(f"{path}: {a!r} != {b!r}")
old, new = Path(sys.argv[1]), Path(sys.argv[2])
ok = True
print("metrics.json byte-identical:", (old/"metrics.json").read_bytes() == (new/"metrics.json").read_bytes())
for name, keys in NORM.items():
    counts, diffs = collections.Counter(), []
    walk(json.loads((old/name).read_text()), json.loads((new/name).read_text()), keys, name, counts, diffs)
    print(name, dict(counts), "other diffs:", len(diffs)); [print("  ", d) for d in diffs[:20]]
    ok &= not diffs
m = json.loads((new/"manifest.json").read_text()); mo = json.loads((old/"manifest.json").read_text())
def dv(x): return x.get("versions", {}).get("derivation") if isinstance(x, dict) else None
print("derivation old/new:", dv(mo), dv(m))
if (old/"performance.json").exists():
    po, pn = json.loads((old/"performance.json").read_text()), json.loads((new/"performance.json").read_text())
    print("performance top-level type", type(po).__name__, list(po)[:5] if isinstance(po, dict) else len(po))
print("OK" if ok else "FAIL")
EOF
